	lintFiles: mockLintFiles,
	lintText: mockLintText,
	loadFormatter: mockLoadFormatter,
	calculateConfigForFile: mockCalculateConfigForFile,
};

const mockESLintConstructor = jest.fn(function ESLint() {
	return mockEngine;
});
mockESLintConstructor.fromOptionsModule = jest.fn();
mockESLintConstructor.outputFixes = jest.fn();
mockESLintConstructor.getErrorResults = jest.fn();

const mockLocateConfigFileToUse = jest.fn();

