//------------------------------------------------------------------------------
// Argument parsing and validation
//------------------------------------------------------------------------------

describe("cli.execute option validation", () => {
	test("reports an unknown option and exits with 2", async () => {
		const exitCode = await cli.execute(argv("--unknown-option"));

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(
			expect.stringContaining("Invalid option '--unknown-option'"),
		);
		expect(mockLintFiles).not.toHaveBeenCalled();
	});

	test.each(["0", "1.5", "not-a-number"])(
		"rejects invalid --concurrency value %s with exit code 2",
		async concurrency => {
			const exitCode = await cli.execute(
				argv("--concurrency", concurrency, "file.js"),
			);

			expect(exitCode).toBe(2);
			expect(errorSpy).toHaveBeenCalledWith(
				`Option concurrency: '${concurrency}' is not a positive integer, 'auto' or 'off'.`,
			);
			expect(mockLintFiles).not.toHaveBeenCalled();
		},
	);

	test("rejects using --fix and --fix-dry-run together", async () => {
		const exitCode = await cli.execute(
			argv("--fix", "--fix-dry-run", "file.js"),
		);

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(
			"The --fix option and the --fix-dry-run option cannot be used together.",
		);
		expect(mockLintFiles).not.toHaveBeenCalled();
	});

	test("rejects --fix with piped-in code", async () => {
		const exitCode = await cli.execute(
			argv("--fix", "file.js"),
			"const answer = 42;",
		);

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(
			"The --fix option is not available for piped-in code; use --fix-dry-run instead.",
		);
		expect(mockLintText).not.toHaveBeenCalled();
	});

	test("rejects --fix-type without --fix or --fix-dry-run", async () => {
		const exitCode = await cli.execute(
			argv("--fix-type", "problem", "file.js"),
		);

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(
			"The --fix-type option requires either --fix or --fix-dry-run.",
		);
	});

	test("rejects conflicting unused-disable-directive options", async () => {
		const exitCode = await cli.execute(
			argv(
				"--report-unused-disable-directives",
				"--report-unused-disable-directives-severity",
				"error",
				"file.js",
			),
		);

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(
			"The --report-unused-disable-directives option and the --report-unused-disable-directives-severity option cannot be used together.",
		);
	});

	test("rejects an empty --ext value", async () => {
		const exitCode = await cli.execute(argv("--ext", "", "file.js"));

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(
			"The --ext option value cannot be empty.",
		);
	});

	test("reports the index of an empty string in --ext", async () => {
		const exitCode = await cli.execute(
			argv("--ext", "ts,,tsx", "file.js"),
		);

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(
			"The --ext option arguments cannot be empty strings. Found an empty string at index 1.",
		);
	});

	test.each([
		[
			["--suppress-all", "--suppress-rule", "no-unused-vars"],
			"The --suppress-all option and the --suppress-rule option cannot be used together.",
		],
		[
			["--suppress-all", "--prune-suppressions"],
			"The --suppress-all option and the --prune-suppressions option cannot be used together.",
		],
		[
			["--suppress-rule", "no-unused-vars", "--prune-suppressions"],
			"The --suppress-rule option and the --prune-suppressions option cannot be used together.",
		],
	])("rejects conflicting suppression options %#", async (args, message) => {
		const exitCode = await cli.execute(argv(...args, "file.js"));

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(message);
		expect(mockLintFiles).not.toHaveBeenCalled();
	});

	test.each([
		["--suppress-all"],
		["--suppress-rule", "no-unused-vars"],
		["--prune-suppressions"],
	])(
		"rejects suppression option %s with piped-in code",
		async (...args) => {
			const exitCode = await cli.execute(
				argv(...args, "file.js"),
				"const answer = 42;",
