//------------------------------------------------------------------------------
// inspect-config
//------------------------------------------------------------------------------

describe("cli.execute --inspect-config", () => {
	test("starts the config inspector with the located config flags", async () => {
		translateOptions.mockResolvedValue({
			overrideConfigFile: "/project/eslint.config.js",
		});
		mockLocateConfigFileToUse.mockResolvedValue({
			configFilePath: "/project/eslint.config.js",
			basePath: "/project",
		});

		const exitCode = await cli.execute(argv("--inspect-config"));

		expect(exitCode).toBe(0);
		expect(infoSpy).toHaveBeenCalledWith(
			"You can also run this command directly using 'npx @eslint/config-inspector@latest' in the same directory as your configuration file.",
		);
		expect(mockLocateConfigFileToUse).toHaveBeenCalledWith({
			cwd: process.cwd(),
			configFile: "/project/eslint.config.js",
		});
		expect(crossSpawn.sync).toHaveBeenCalledWith(
			"npx",
			[
				"@eslint/config-inspector@latest",
				"--config",
				"/project/eslint.config.js",
				"--basePath",
				"/project",
			],
			{ encoding: "utf8", stdio: "inherit" },
		);
	});

	test("logs the error and exits with 2 when the inspector cannot start", async () => {
		const spawnError = new Error("cannot spawn inspector");

		translateOptions.mockResolvedValue({});
		mockLocateConfigFileToUse.mockResolvedValue({
			configFilePath: "/project/eslint.config.js",
			basePath: "/project",
		});
		crossSpawn.sync.mockImplementation(() => {
			throw spawnError;
		});

		const exitCode = await cli.execute(argv("--inspect-config"));

		expect(exitCode).toBe(2);
		expect(errorSpy).toHaveBeenCalledWith(spawnError);
	});

	test("calculateInspectConfigFlags maps the located config to CLI flags", async () => {
		mockLocateConfigFileToUse.mockResolvedValue({
			configFilePath: "/project/eslint.config.js",
			basePath: "/project",
		});

		const flags = await cli.calculateInspectConfigFlags(
			"/project/eslint.config.js",
		);

		expect(flags).toEqual([
			"--config",
			"/project/eslint.config.js",
			"--basePath",
			"/project",
		]);
		expect(mockLocateConfigFileToUse).toHaveBeenCalledWith({
			cwd: process.cwd(),
			configFile: "/project/eslint.config.js",
		});
	});

	test("calculateInspectConfigFlags discovers a config file in the working directory", async () => {
		const actualEslint = jest.requireActual("../../lib/eslint/eslint");
		const dir = makeTempDir();
		const configPath = path.join(dir, "eslint.config.js");

		fs.writeFileSync(configPath, "module.exports = [];\n");
		process.chdir(dir);
		mockLocateConfigFileToUse.mockImplementation(
			actualEslint.locateConfigFileToUse,
		);

		const flags = await cli.calculateInspectConfigFlags();

		expect(flags).toEqual([
			"--config",
			configPath,
			"--basePath",
			dir,
		]);
	});
});

//------------------------------------------------------------------------------
// Lint execution, formatter, output, and exit codes
//------------------------------------------------------------------------------

describe("cli.execute linting behavior", () => {
	test("lints positional files, prints the formatter output, and exits 0", async () => {
		const exitCode = await cli.execute(argv("file.js", "src"));

		expect(exitCode).toBe(0);
		expect(translateOptions).toHaveBeenCalledTimes(1);
		expect(mockLintFiles).toHaveBeenCalledWith(["file.js", "src"]);
		expect(mockLoadFormatter).toHaveBeenCalledWith("stylish");
		expect(formatMock).toHaveBeenCalledWith([], {});
		expect(infoSpy).toHaveBeenCalledWith("formatted report");
	});

	test("returns 1 when lint results contain errors", async () => {
		mockLintFiles.mockResolvedValue([
			makeResult({ messages: [makeMessage(2)] }),
		]);

		const exitCode = await cli.execute(argv("file.js"));

		expect(exitCode).toBe(1);
	});

	test("returns 0 when warnings do not exceed --max-warnings", async () => {
		mockLintFiles.mockResolvedValue([
			makeResult({ messages: [makeMessage(1)] }),
		]);

		const exitCode = await cli.execute(
			argv("--max-warnings", "1", "file.js"),
		);

		expect(exitCode).toBe(0);
		expect(errorSpy).not.toHaveBeenCalled();
	});

	test("returns 1 and mentions the maximum when warnings exceed --max-warnings", async () => {
		const results = [makeResult({ messages: [makeMessage(1)] })];

		mockLintFiles.mockResolvedValue(results);

		const exitCode = await cli.execute(
			argv("--max-warnings", "0", "file.js"),
		);

		expect(exitCode).toBe(1);
		expect(errorSpy).toHaveBeenCalledWith(
			"ESLint found too many warnings (maximum: %s).",
