		const exitCode = await cli.execute(
			argv("--max-warnings", "0", "file.js"),
		);

		expect(exitCode).toBe(1);
		expect(errorSpy).not.toHaveBeenCalledWith(
			"ESLint found too many warnings (maximum: %s).",
			0,
		);
	});

	test("filters warnings from formatter output in quiet mode", async () => {
		const errorResult = makeResult({ messages: [makeMessage(2)] });
		const warningResult = makeResult({ messages: [makeMessage(1)] });
		const results = [errorResult, warningResult];

		mockLintFiles.mockResolvedValue(results);

		const exitCode = await cli.execute(argv("--quiet", "file.js"));

		expect(exitCode).toBe(1);
		expect(mockESLintConstructor.getErrorResults).toHaveBeenCalledWith(
			results,
		);
		expect(formatMock).toHaveBeenCalledWith([errorResult], {});
	});

	test("applies fixes when --fix is used", async () => {
		const results = [makeResult()];

		mockLintFiles.mockResolvedValue(results);

		const exitCode = await cli.execute(argv("--fix", "file.js"));

		expect(exitCode).toBe(0);
		expect(mockESLintConstructor.outputFixes).toHaveBeenCalledWith(results);
	});

	test("does not write fixes when --fix-dry-run is used", async () => {
		const exitCode = await cli.execute(
			argv("--fix-dry-run", "file.js"),
		);

		expect(exitCode).toBe(0);
		expect(mockESLintConstructor.outputFixes).not.toHaveBeenCalled();
