describe("calculateWorkerCount", () => {
	it("uses zero workers when concurrency is off or resolves to one worker", () => {
		const cwd = os.tmpdir();
		const off = new ESLint({
			cwd,
			overrideConfigFile: true,
			overrideConfig: { rules: {} },
			concurrency: "off",
		});
		const single = new ESLint({
			cwd,
			overrideConfigFile: true,
			overrideConfig: { rules: {} },
			concurrency: 1,
		});

		expect(calculateWorkerCount(off, ["a.js"])).toBe(0);
		expect(calculateWorkerCount(single, ["a.js", "b.js"])).toBe(0);
	});

	it("caps numeric concurrency at the number of files", () => {
		const cwd = os.tmpdir();
		const eslint = new ESLint({
			cwd,
			overrideConfigFile: true,
			overrideConfig: { rules: {} },
			concurrency: 5,
		});

		expect(calculateWorkerCount(eslint, ["a.js", "b.js"])).toBe(2);
		expect(
			calculateWorkerCount(eslint, [
				"a.js",
				"b.js",
				"c.js",
				"d.js",
				"e.js",
				"f.js",
			]),
		).toBe(5);
	});

	it("calculates auto concurrency from processable files and available CPUs", async () => {
		const cwd = await createTempDir();
		const eslint = new ESLint({
			cwd,
			overrideConfigFile: true,
			overrideConfig: { rules: {} },
			concurrency: "auto",
		});

		await eslint.calculateConfigForFile("file-0.js");

		/**
		 * Creates a list of file paths for the given count.
		 * @param {number} count The number of paths to create.
		 * @returns {string[]} The generated file paths.
		 */
		function files(count) {
			return Array.from({ length: count }, (_, index) =>
				path.join(cwd, `file-${index}.js`),
			);
		}
		const mockOs = { availableParallelism: () => 10 };

		expect(calculateWorkerCount(eslint, files(50), mockOs)).toBe(0);
		expect(calculateWorkerCount(eslint, files(51), mockOs)).toBe(2);
		expect(calculateWorkerCount(eslint, files(101), mockOs)).toBe(3);
		expect(calculateWorkerCount(eslint, files(300), mockOs)).toBe(5);
	});

	it("does not count ignored files when calculating auto concurrency", async () => {
		const cwd = await createTempDir();
		const eslint = new ESLint({
			cwd,
			overrideConfigFile: true,
			overrideConfig: [{ ignores: ["ignored-*.js"] }, { rules: {} }],
			concurrency: "auto",
		});

		await eslint.calculateConfigForFile("ignored-0.js");

		const ignoredFiles = Array.from({ length: 100 }, (_, index) =>
			path.join(cwd, `ignored-${index}.js`),
		);
