			"function f(undefined) { return undefined; }",
		);
		const fn1 = parameterUndefined.ast.body[0];
		const scope1 = parameterUndefined.scopeManager.acquire(fn1);

		expect(
			astUtils.isConstant(
				scope1,
				findNode(fn1, "ReturnStatement").argument,
				true,
			),
		).toBe(false);

		const parameterBoolean = parse(
			"function f(Boolean) { return Boolean(1); }",
		);
		const fn2 = parameterBoolean.ast.body[0];
		const scope2 = parameterBoolean.scopeManager.acquire(fn2);

		expect(
			astUtils.isConstant(
				scope2,
				findNode(fn2, "ReturnStatement").argument,
				true,
			),
		).toBe(false);

		const localBoolean = parse(
			"function f() { const Boolean = value => value; return Boolean(1); }",
		);
		const fn3 = localBoolean.ast.body[0];
		const scope3 = localBoolean.scopeManager.acquire(fn3);

		expect(
			astUtils.isConstant(
				scope3,
				findNode(fn3, "ReturnStatement").argument,
				true,
			),
		).toBe(false);

		const localUndefined = parse("const undefined = 1; undefined;");
		const globalScope = localUndefined.scopeManager.scopes[0];

		expect(
			astUtils.isConstant(
				globalScope,
				localUndefined.ast.body[1].expression,
				true,
			),
		).toBe(false);
	});

	test("isPropertyDescriptor handles Object and Reflect defineProperty calls", () => {
		for (const code of [
			'Object.defineProperty(obj, "x", { value: 1 });',
			'Reflect.defineProperty(obj, "x", { value: 1 });',
		]) {
			const { ast, sourceCode } = parse(code, {
				globals: ["Object", "Reflect"],
			});
			const call = ast.body[0].expression;
			const descriptor = call.arguments[2];

			expect(astUtils.isPropertyDescriptor(descriptor, sourceCode)).toBe(
				true,
			);
		}
	});

	test("isPropertyDescriptor handles descriptor maps for create and defineProperties", () => {
		for (const code of [
			"Object.create(null, { x: { value: 1 } });",
			"Object.defineProperties(obj, { x: { value: 1 } });",
		]) {
			const { ast, sourceCode } = parse(code, { globals: ["Object"] });
			const call = ast.body[0].expression;
			const descriptor = call.arguments[1].properties[0].value;

			expect(astUtils.isPropertyDescriptor(descriptor, sourceCode)).toBe(
				true,
			);
		}
	});

	test("isPropertyDescriptor rejects objects outside descriptor positions", () => {
		const ordinary = parse("const descriptor = { value: 1 };", {
			globals: ["Object"],
		});

		expect(
			astUtils.isPropertyDescriptor(
				ordinary.ast.body[0].declarations[0].init,
				ordinary.sourceCode,
			),
		).toBe(false);

		const argument = parse("foo({ value: 1 });", {
			globals: ["Object"],
		});

		expect(
			astUtils.isPropertyDescriptor(
				argument.ast.body[0].expression.arguments[0],
				argument.sourceCode,
			),
		).toBe(false);

		const someObject = parse(
			'SomeObject.defineProperty(obj, "x", { value: 1 });',
			{ globals: ["Object"] },
		);

		expect(
			astUtils.isPropertyDescriptor(
				someObject.ast.body[0].expression.arguments[2],
				someObject.sourceCode,
			),
		).toBe(false);
	});

	test("isPropertyDescriptor rejects shadowed Object globals", () => {
		const { ast, sourceCode } = parse(
			'function f(Object) { Object.defineProperty(obj, "x", { value: 1 }); }',
			{ globals: ["Object"] },
		);
		const call = findNode(ast, "CallExpression");

		expect(
			astUtils.isPropertyDescriptor(call.arguments[2], sourceCode),
		).toBe(false);
	});
});

describe("isDefaultThisBinding", () => {
	test.each([
		["function foo() {}", true, true],
		["function Foo() {}", false, true],
		["({ foo() {} })", false, false],
		["({ foo: function () {} })", false, false],
		["({ foo: function bar() {} })", false, false],
		["class A { foo = function () {}; }", false, false],
		["foo = function () {}", true, true],
		["Foo = function () {}", false, true],
		["var foo = function () {}", true, true],
		["var Foo = function () {}", false, true],
		["var Foo = function bar() {}", true, true],
		["(function foo() {}).bind(obj)", false, false],
		["(function foo() {}).bind(null)", true, true],
		["[].forEach(function () {}, obj)", false, false],
		["[].forEach(function () {})", true, true],
		["Reflect.apply(function () {}, obj, [])", false, false],
		["Array.from([], function () {}, obj)", false, false],
		["foo(function bar() {})", true, true],
		["cond ? function () {} : null", true, true],
		["Object.assign({}, { m() {} })", false, false],
	])(
		"evaluates this binding for %s",
		(code, expected, expectedWithoutConstructorCap) => {
			const { ast, sourceCode } = parse(code);
			const fn = findFunction(ast);

			expect(fn).toBeDefined();
			expect(astUtils.isDefaultThisBinding(fn, sourceCode)).toBe(
				expected,
			);
			expect(
				astUtils.isDefaultThisBinding(fn, sourceCode, {
					capIsConstructor: false,
				}),
			).toBe(expectedWithoutConstructorCap);
		},
	);

	test("class static blocks never have default this binding", () => {
		const { ast, sourceCode } = parse("class A { static {} }");
		const staticBlock = findNode(ast, "StaticBlock");

		expect(astUtils.isDefaultThisBinding(staticBlock, sourceCode)).toBe(
			false,
		);
	});

	test("JSDoc @this tags disable default this binding", () => {
		const declaration = parse("/* @this */ function foo() {}");

		expect(
			astUtils.isDefaultThisBinding(
				findFunction(declaration.ast),
				declaration.sourceCode,
			),
		).toBe(false);

		const callback = parse(
			"sinon.test(/* @this sandbox */ function () {});",
		);

		expect(
			astUtils.isDefaultThisBinding(
				findFunction(callback.ast),
				callback.sourceCode,
			),
		).toBe(false);
	});

	test("non-JSDoc block comments do not affect this binding", () => {
		const { ast, sourceCode } = parse(
			"/* regular comment */ function foo() {}",
		);

		expect(
			astUtils.isDefaultThisBinding(findFunction(ast), sourceCode),
		).toBe(true);
	});
});

