describe("getPrecedence", () => {
	test.each([
		["a, b", 0],
		["a = b", 1],
		["() => {}", 1],
		["a ? b : c", 3],
		["a || b", 4],
		["a ?? b", 4],
		["a && b", 5],
		["a | b", 6],
		["a ^ b", 7],
		["a & b", 8],
		["a == b", 9],
		["a < b", 10],
		["a << b", 11],
		["a + b", 12],
		["a * b", 13],
		["a ** b", 15],
		["-a", 16],
		["a++", 17],
		["a()", 18],
		["a?.b", 18],
		["new A()", 19],
		["a", 20],
	])("returns the precedence of %s", (code, expected) => {
		expect(astUtils.getPrecedence(parseExpression(code).node)).toBe(
			expected,
		);
	});

	test("returns precedence for await, yield, import and unknown nodes", () => {
		const { ast } = parse(
			"async function f() { await a; }\nfunction* g() { yield a; }\nimport('x');",
		);

		expect(astUtils.getPrecedence(findNode(ast, "AwaitExpression"))).toBe(
			16,
		);
		expect(astUtils.getPrecedence(findNode(ast, "YieldExpression"))).toBe(
			1,
		);
		expect(astUtils.getPrecedence(findNode(ast, "ImportExpression"))).toBe(
			18,
		);
		expect(astUtils.getPrecedence({ type: "CustomUnknownNode" })).toBe(-1);
	});

	test("returns default precedence for known non-operator nodes", () => {
		const { ast } = parse("class A {}");

		expect(astUtils.getPrecedence(ast.body[0])).toBe(20);
	});
});

describe("block and directive helpers", () => {
	test("isEmptyBlock recognizes only empty BlockStatements", () => {
		expect(
			astUtils.isEmptyBlock(parse("if (a) {}").ast.body[0].consequent),
		).toBe(true);
		expect(
			astUtils.isEmptyBlock(
				parse("if (a) { foo(); }").ast.body[0].consequent,
			),
		).toBe(false);
		expect(astUtils.isEmptyBlock(null)).toBe(false);
		expect(
			astUtils.isEmptyBlock({ type: "ObjectExpression", body: [] }),
		).toBe(false);
	});

	test("isEmptyFunction recognizes functions with empty block bodies", () => {
		expect(astUtils.isEmptyFunction(parseExpression("() => {}").node)).toBe(
			true,
		);
		expect(
			astUtils.isEmptyFunction(parseExpression("(function () {})").node),
		).toBe(true);
		expect(
			astUtils.isEmptyFunction(parseExpression("async () => {}").node),
		).toBe(true);
		expect(
			astUtils.isEmptyFunction(
				parseExpression("(function () { foo(); })").node,
			),
		).toBe(false);
		expect(astUtils.isEmptyFunction(parseExpression("() => 1").node)).toBe(
			false,
		);
		expect(astUtils.isEmptyFunction(null)).toBe(false);
	});

	test("getDirectivePrologue collects leading directives from a Program", () => {
		const { ast } = parse('"use strict"; foo(); "not directive";');
		const directives = astUtils.getDirectivePrologue(ast);

		expect(directives).toHaveLength(1);
		expect(directives[0].expression.value).toBe("use strict");
	});

	test("getDirectivePrologue collects directives from function bodies", () => {
		const { ast } = parse('function f() { "use strict"; foo(); }');
		const directives = astUtils.getDirectivePrologue(ast.body[0]);

		expect(directives).toHaveLength(1);
		expect(directives[0].expression.value).toBe("use strict");

		const arrow = parse('() => { "use strict"; }');
		const arrowDirectives = astUtils.getDirectivePrologue(
			findNode(arrow.ast, "ArrowFunctionExpression"),
		);

		expect(arrowDirectives).toHaveLength(1);
	});

	test("getDirectivePrologue ignores non-block arrows and non-functions", () => {
		const arrow = parse('() => "use strict"');
		const arrowBlock = parse("function f() {}");
		const classDeclaration = parse("class A {}");

		expect(
			astUtils.getDirectivePrologue(
				findNode(arrow.ast, "ArrowFunctionExpression"),
			),
		).toEqual([]);
		expect(astUtils.getDirectivePrologue(arrowBlock.ast.body[0])).toEqual(
			[],
		);
		expect(
			astUtils.getDirectivePrologue(classDeclaration.ast.body[0]),
		).toEqual([]);
	});

	test("isDirective checks for directive property on expression statements", () => {
		expect(astUtils.isDirective(parse('"use strict";').ast.body[0])).toBe(
			true,
		);
		expect(astUtils.isDirective(parse("foo();").ast.body[0])).toBe(false);
		expect(astUtils.isDirective(parse('("use strict");').ast.body[0])).toBe(
			false,
		);
		expect(astUtils.isDirective(parse("`text`;").ast.body[0])).toBe(false);
	});
});

