		).toBe("true");
		expect(
			astUtils.getStaticStringValue(parseExpression("`abc`").node),
		).toBe("abc");
		expect(
			astUtils.getStaticStringValue(parseExpression("`a${b}c`").node),
		).toBeNull();
		expect(
			astUtils.getStaticStringValue(parseExpression("undefined").node),
		).toBeNull();
	});

	test.each([
		["a.b", "b"],
		['a["b"]', "b"],
