			astUtils.getStaticPropertyName(parsePropertyLikeNode(code)),
		).toBe(expected);
	});

	test("skipChainExpression unwraps ChainExpression nodes only", () => {
		const chain = parseExpression("a?.b").node;
		const identifier = parseExpression("a").node;

		expect(chain.type).toBe("ChainExpression");
		expect(astUtils.skipChainExpression(chain)).toBe(chain.expression);
		expect(astUtils.skipChainExpression(identifier)).toBe(identifier);
		expect(astUtils.skipChainExpression(null)).toBeNull();
	});

	test("isSpecificId checks names and patterns", () => {
		const identifier = { type: "Identifier", name: "foo" };

		expect(astUtils.isSpecificId(identifier, "foo")).toBe(true);
		expect(astUtils.isSpecificId(identifier, /^f/)).toBe(true);
		expect(astUtils.isSpecificId(identifier, "bar")).toBe(false);
		expect(astUtils.isSpecificId(identifier, /^b/)).toBe(false);
		expect(astUtils.isSpecificId({ type: "MemberExpression" }, "foo")).toBe(
			false,
		);
	});

	test.each([
