		["-", "--", false],
		["-", "+", true],
		["/", "/* block */", false],
		["/", "// line\n", false],
		["a", "b", false],
		["a", "/* block */", true],
		["a", "// line\n", true],
		['"a"', '"b"', true],
		["`a`", "b", true],
		["a", "#b", true],
		["1", ".5", false],
		["a", ".5", true],
		["#!/usr/bin/env node", "foo", false],
		["a", "1", false],
		['"', "a", false],
		["a", '"', false],
	])("canTokensBeAdjacent(%j, %j) is %s", (left, right, expected) => {
