describe("areBracesNecessary", () => {
	test.each([
		["if (a) { let x; }", true],
		["if (a) { const x = 1; }", true],
		["if (a) { function f() {} }", true],
		["if (a) { class B {} }", true],
		["if (a) { var x; }", false],
		["if (a) { if (b) foo(); } else bar();", true],
		["if (a) { if (b) foo(); }", false],
		["if (a) { if (b) foo(); else baz(); } else bar();", false],
		["if (a) { while (b) if (c) foo(); } else bar();", true],
		["if (a) { foo(); } else bar();", false],
		["if (a) { function f() {} } else bar();", true],
		["if (a) { class B {} } else bar();", true],
		["if (a) { { if (b) foo(); } } else bar();", false],
		["if (a) { if (b) foo(); else if (c) bar(); } else baz();", true],
	])("reports brace necessity for %s", (code, expected) => {
		const { ast, sourceCode } = parse(code);
		const block = findNode(ast, "BlockStatement");

		expect(astUtils.areBracesNecessary(block, sourceCode)).toBe(expected);
	});
});

describe("top-level expression and statement helpers", () => {
	test.each([
		["foo();", true],
		["function f() { foo(); }", true],
		["() => { foo(); }", true],
		["if (a) { foo(); }", false],
		["function f() { if (a) { foo(); } }", false],
		["class A { m() { foo(); } }", true],
	])("isTopLevelExpressionStatement for %s", (code, expected) => {
		const { ast } = parse(code);
		const statement = findNodes(ast, "ExpressionStatement").find(
			node => node.expression.type === "CallExpression",
		);

		expect(statement).toBeDefined();
		expect(astUtils.isTopLevelExpressionStatement(statement)).toBe(
			expected,
		);
	});

	test("isTopLevelExpressionStatement rejects non-expression statements", () => {
		const { ast } = parse("if (a) foo();");

		expect(astUtils.isTopLevelExpressionStatement(ast.body[0])).toBe(false);
	});

	test("isStartOfExpressionStatement checks the start of ancestor statements", () => {
		const member = parse("foo.bar;");
		const memberIdentifiers = findNodes(member.ast, "Identifier");

		expect(
			astUtils.isStartOfExpressionStatement(memberIdentifiers[0]),
		).toBe(true);
		expect(
			astUtils.isStartOfExpressionStatement(memberIdentifiers[1]),
		).toBe(false);

		const binary = parse("foo + bar;");
		const binaryIdentifiers = findNodes(binary.ast, "Identifier");

		expect(
			astUtils.isStartOfExpressionStatement(binaryIdentifiers[0]),
		).toBe(true);
		expect(
			astUtils.isStartOfExpressionStatement(binaryIdentifiers[1]),
		).toBe(false);

		const parenthesised = parse("(foo);");
		const parenthesisedIdentifier = findNode(
			parenthesised.ast,
			"Identifier",
		);

		expect(
			astUtils.isStartOfExpressionStatement(parenthesisedIdentifier),
		).toBe(false);

		const call = parse("foo();");
		const callIdentifier = findNode(call.ast, "Identifier");

		expect(astUtils.isStartOfExpressionStatement(callIdentifier)).toBe(
			true,
		);
	});

	test("canContinueExpressionInClassBody recognizes continuation tokens", () => {
		const cases = [
			["Punctuator", "[", true],
			["Punctuator", "*", true],
			["Punctuator", "(", false],
			["Identifier", "in", true],
			["Keyword", "in", true],
			["Identifier", "instanceof", true],
			["Keyword", "instanceof", true],
			["Keyword", "if", false],
			["Identifier", "foo", false],
		];

		for (const [type, value, expected] of cases) {
			expect(
				astUtils.canContinueExpressionInClassBody({ type, value }),
			).toBe(expected);
		}
	});

	test("getTrailingStatement returns the trailing statement of block statements", () => {
		const withElse = parse("if (a) foo(); else bar();");
		const trailing = astUtils.getTrailingStatement(withElse.ast.body[0]);

		expect(trailing.type).toBe("ExpressionStatement");
		expect(withElse.sourceCode.getText(trailing)).toBe("bar();");

		const withBlock = parse("while (a) { foo(); }");
		const trailingBlock = astUtils.getTrailingStatement(
			withBlock.ast.body[0],
		);

		expect(trailingBlock.type).toBe("BlockStatement");
	});
});

describe("needsPrecedingSemicolon", () => {
	test.each([
		["foo;\nbar();", false],
		["foo\nbar();", true],
		["var x\nfoo();", false],
		["var x = 1\nfoo();", true],
		["(function () {})\nfoo();", true],
		["const f = function () {}\nfoo();", true],
		["class C {}\nfoo();", false],
		["if (a) {}\nfoo();", false],
		["do foo(); while (a)\nbar();", false],
		['import x from "x"\nfoo();', false],
		["const o = {}\nfoo();", true],
		["const C = class {}\nfoo();", true],
	])("returns the right answer for %j", (code, expected) => {
		const { ast, sourceCode } = parse(code, { sourceType: "module" });

		expect(ast.body).toHaveLength(2);
		expect(astUtils.needsPrecedingSemicolon(sourceCode, ast.body[1])).toBe(
			expected,
		);
	});

	test("handles class members after initializers", () => {
		const initialized = parse("class A {\nfoo = 1\nbar() {}\n}");
		const initializedMembers = initialized.ast.body[0].body.body;

		expect(
			astUtils.needsPrecedingSemicolon(
				initialized.sourceCode,
				initializedMembers[1],
			),
		).toBe(true);

		const uninitialized = parse("class A {\nfoo\nbar() {}\n}");
		const uninitializedMembers = uninitialized.ast.body[0].body.body;

		expect(
			astUtils.needsPrecedingSemicolon(
				uninitialized.sourceCode,
				uninitializedMembers[1],
			),
		).toBe(false);

		const computed = parse("class A {\n[foo]() {}\nbar() {}\n}");
		const computedMembers = computed.ast.body[0].body.body;

		expect(
			astUtils.needsPrecedingSemicolon(
				computed.sourceCode,
				computedMembers[1],
			),
		).toBe(false);
	});
});

describe("isImportAttributeKey", () => {
	test("recognizes static import attribute keys", () => {
		const key = { type: "Identifier", name: "type" };
		const importAttribute = { type: "ImportAttribute", key };

		key.parent = importAttribute;

		expect(astUtils.isImportAttributeKey(key)).toBe(true);

		const value = {
			type: "Literal",
			value: "json",
			parent: importAttribute,
		};

		importAttribute.value = value;

		expect(astUtils.isImportAttributeKey(value)).toBe(false);
	});

	test("recognizes dynamic import attribute keys", () => {
		const key = { type: "Identifier", name: "type" };
		const options = { type: "ObjectExpression" };
		const property = {
			type: "Property",
			computed: false,
			shorthand: false,
			method: false,
			key,
			value: { type: "Literal", value: "json" },
			parent: options,
		};

		key.parent = property;
		options.parent = { type: "ImportExpression", options };

		expect(astUtils.isImportAttributeKey(key)).toBe(true);
	});

	test("recognizes nested dynamic import attribute keys", () => {
		const importExpression = { type: "ImportExpression" };
		const outerOptions = {
			type: "ObjectExpression",
			parent: importExpression,
		};
		const innerOptions = { type: "ObjectExpression" };

		importExpression.options = outerOptions;

		const withKey = { type: "Identifier", name: "with" };
		const outerProperty = {
			type: "Property",
			computed: false,
			shorthand: false,
			method: false,
			key: withKey,
			value: innerOptions,
			parent: outerOptions,
		};

		withKey.parent = outerProperty;
		innerOptions.parent = outerProperty;

		const typeKey = { type: "Identifier", name: "type" };
		const innerProperty = {
			type: "Property",
			computed: false,
			shorthand: false,
			method: false,
			key: typeKey,
			value: { type: "Literal", value: "json" },
			parent: innerOptions,
		};

		typeKey.parent = innerProperty;

		expect(astUtils.isImportAttributeKey(typeKey)).toBe(true);
	});

	test("rejects keys outside of import attributes", () => {
		const key = { type: "Identifier", name: "type" };
		const options = {
			type: "ObjectExpression",
			parent: { type: "CallExpression" },
		};
		const property = {
			type: "Property",
			computed: false,
			shorthand: false,
			method: false,
			key,
			value: { type: "Literal", value: "json" },
			parent: options,
		};

		key.parent = property;
		options.parent = options.parent;

		expect(astUtils.isImportAttributeKey(key)).toBe(false);
	});
});

describe("getOpeningParenOfParams", () => {
	test("finds the opening parenthesis for function declarations and methods", () => {
		const { ast, sourceCode } = parse(
			"function foo(a) {}\nclass A { m(b) {} }",
		);
		const declaration = ast.body[0];
		const method = findNode(ast, "FunctionExpression");

		expect(
			astUtils.getOpeningParenOfParams(declaration, sourceCode),
		).toMatchObject({ type: "Punctuator", value: "(", range: [12, 13] });
		expect(
			astUtils.getOpeningParenOfParams(method, sourceCode),
		).toMatchObject({
			type: "Punctuator",
			value: "(",
		});
	});

	test("finds the opening parenthesis for parenthesized arrows", () => {
		const { ast, sourceCode } = parse(
			"const f = (a) => a;\nconst g = async (b) => b;",
		);
		const arrows = findNodes(ast, "ArrowFunctionExpression");

		for (const arrow of arrows) {
			expect(
				astUtils.getOpeningParenOfParams(arrow, sourceCode).value,
			).toBe("(");
		}
	});

	test("returns the parameter token for an unparenthesized arrow", () => {
		const { ast, sourceCode } = parse("const f = value => value;");
		const arrow = findNode(ast, "ArrowFunctionExpression");
		const param = arrow.params[0];
		const token = astUtils.getOpeningParenOfParams(arrow, sourceCode);

		expect(token.value).toBe("value");
		expect(token.range).toEqual(param.range);
	});
});

describe("isParenthesised and equalTokens", () => {
	test("isParenthesised checks for immediate surrounding parentheses", () => {
		const parenthesised = parse("(foo);");
		const parenthesisedIdentifier = findNode(
			parenthesised.ast,
			"Identifier",
		);

		expect(
			astUtils.isParenthesised(
				parenthesised.sourceCode,
				parenthesisedIdentifier,
			),
		).toBe(true);

		const bare = parse("foo;");
		const bareIdentifier = findNode(bare.ast, "Identifier");

		expect(astUtils.isParenthesised(bare.sourceCode, bareIdentifier)).toBe(
			false,
		);

		const addend = parse("(foo) + bar;");
		const addendIdentifier = findNodes(addend.ast, "Identifier")[0];

		expect(
			astUtils.isParenthesised(addend.sourceCode, addendIdentifier),
		).toBe(true);
	});

	test("isParenthesised rejects parentheses around a larger expression", () => {
		const { ast, sourceCode } = parse("(foo + bar);");
		const left = findNodes(ast, "Identifier")[0];

		expect(astUtils.isParenthesised(sourceCode, left)).toBe(false);
	});

	test("equalTokens compares token types and values", () => {
		const { ast, sourceCode } = parse("foo(bar); foo(bar); foo(baz);");
		const calls = findNodes(ast, "CallExpression");

		expect(astUtils.equalTokens(calls[0], calls[1], sourceCode)).toBe(true);
		expect(astUtils.equalTokens(calls[0], calls[2], sourceCode)).toBe(
			false,
		);
	});

	test("equalTokens rejects nodes with different token counts", () => {
		const { ast, sourceCode } = parse("foo; foo.bar;");
		const [identifier, memberExpression] = [
			ast.body[0].expression,
			ast.body[1].expression,
		];

		expect(
			astUtils.equalTokens(identifier, memberExpression, sourceCode),
		).toBe(false);
	});
});

