const astUtils = require("../../../../lib/rules/utils/ast-utils");

//------------------------------------------------------------------------------
// Helpers
//------------------------------------------------------------------------------

/**
 * Adds parent links to every node in an ESTree AST.
 * @param {ASTNode} node The node to start from.
 * @param {ASTNode|null} parent The parent node.
 * @returns {ASTNode} The input node.
 */
function attachParents(node, parent = null) {
	node.parent = parent;

	for (const key of KEYS[node.type] || []) {
		const child = node[key];

		if (Array.isArray(child)) {
			for (const item of child) {
				if (item && typeof item.type === "string") {
					attachParents(item, node);
				}
			}
		} else if (child && typeof child.type === "string") {
			attachParents(child, node);
		}
	}

	return node;
}

/**
 * Parses code and creates a SourceCode instance with parent links and scopes.
 * @param {string} code The code to parse.
 * @param {Object} [options] Options.
 * @param {string} [options.sourceType] The source type.
 * @param {string[]} [options.globals] Global variable names to declare.
 * @returns {{ast: ASTNode, sourceCode: SourceCode, scopeManager: Object}} The result.
 */
function parse(code, { sourceType = "script", globals = [] } = {}) {
	const ast = attachParents(
		espree.parse(code, {
			ecmaVersion: "latest",
			sourceType,
			loc: true,
			range: true,
			tokens: true,
			comment: true,
		}),
	);
	const scopeManager = eslintScope.analyze(ast, {
		ecmaVersion: 2022,
		sourceType,
		childVisitorKeys: KEYS,
		fallback: node => KEYS[node.type] || [],
	});

	if (globals.length > 0) {
		scopeManager.addGlobals(globals);
	}

	return {
		ast,
		sourceCode: new SourceCode({ text: code, ast, scopeManager }),
		scopeManager,
	};
}

/**
 * Finds all nodes of a given type in pre-order.
 * @param {ASTNode} node The node to start from.
 * @param {string} type The node type to find.
 * @param {ASTNode[]} [results] The accumulator.
 * @returns {ASTNode[]} The matching nodes.
 */
function findNodes(node, type, results = []) {
	if (node.type === type) {
		results.push(node);
	}

	for (const key of KEYS[node.type] || []) {
		const child = node[key];

		if (Array.isArray(child)) {
			for (const item of child) {
				if (item && typeof item.type === "string") {
					findNodes(item, type, results);
				}
			}
		} else if (child && typeof child.type === "string") {
			findNodes(child, type, results);
		}
	}

	return results;
}

/**
 * Finds the first node of a given type.
 * @param {ASTNode} node The node to start from.
 * @param {string} type The node type to find.
 * @returns {ASTNode} The first matching node.
 */
function findNode(node, type) {
	const [result] = findNodes(node, type);

	if (!result) {
		throw new Error(`No ${type} node found.`);
	}

	return result;
}

/**
 * Parses a single expression statement and returns its expression node.
 * @param {string} expression The expression source.
 * @param {Object} [options] Parse options.
 * @returns {{node: ASTNode, ast: ASTNode, sourceCode: SourceCode, scopeManager: Object}} The result.
 */
function parseExpression(expression, options) {
	const result = parse(`${expression};`, options);

	return { ...result, node: result.ast.body[0].expression };
}

/**
 * Parses two expression statements and returns both expression nodes.
 * @param {string} left The left expression source.
 * @param {string} right The right expression source.
 * @param {Object} [options] Parse options.
 * @returns {{left: ASTNode, right: ASTNode, ast: ASTNode, sourceCode: SourceCode}} The result.
 */
function parseTwoExpressions(left, right, options) {
	const result = parse(`${left};\n${right};`, options);

	return {
		...result,
		left: result.ast.body[0].expression,
		right: result.ast.body[1].expression,
	};
}

/**
 * Finds the first function-like node in pre-order.
 * @param {ASTNode} ast The AST to search.
 * @returns {ASTNode} The first function node.
 */
function findFunction(ast) {
	return [
		...findNodes(ast, "FunctionDeclaration"),
		...findNodes(ast, "FunctionExpression"),
		...findNodes(ast, "ArrowFunctionExpression"),
	][0];
}

/**
 * Gets the node whose property name is relevant for getStaticPropertyName().
 * @param {string} code The source code.
 * @returns {ASTNode} The property-like or member expression node.
 */
function parsePropertyLikeNode(code) {
	const { ast } = parse(code);
	const statement = ast.body[0];

	if (statement.type === "ClassDeclaration") {
		return statement.body.body[0];
	}

	if (statement.expression.type === "ObjectExpression") {
		return statement.expression.properties[0];
	}

	return statement.expression;
}

//------------------------------------------------------------------------------
// Exported constants
//------------------------------------------------------------------------------

describe("ast-utils exported constants", () => {
	test("LINEBREAKS contains all ECMAScript line terminators", () => {
		expect(astUtils.LINEBREAKS).toBeInstanceOf(Set);
		expect([...astUtils.LINEBREAKS]).toEqual([
			"\r\n",
			"\r",
			"\n",
			"\u2028",
			"\u2029",
		]);
	});

	test("LINEBREAK_MATCHER matches every line terminator sequence", () => {
		expect(astUtils.LINEBREAK_MATCHER.test("a\r\nb")).toBe(true);
		expect(astUtils.LINEBREAK_MATCHER.test("a\rb")).toBe(true);
		expect(astUtils.LINEBREAK_MATCHER.test("a\nb")).toBe(true);
		expect(astUtils.LINEBREAK_MATCHER.test("a\u2028b")).toBe(true);
		expect(astUtils.LINEBREAK_MATCHER.test("a\u2029b")).toBe(true);
		expect(astUtils.LINEBREAK_MATCHER.test("abc")).toBe(false);
	});

	test("SHEBANG_MATCHER captures the interpreter line", () => {
		const match = astUtils.SHEBANG_MATCHER.exec(
			"#!/usr/bin/env node\nconsole.log(1);",
		);

		expect(match).not.toBeNull();
		expect(match[1]).toBe("/usr/bin/env node");
		expect(astUtils.SHEBANG_MATCHER.test("console.log(1);")).toBe(false);
	});

	test("STATEMENT_LIST_PARENTS contains the statement-list node types", () => {
		expect(astUtils.STATEMENT_LIST_PARENTS).toBeInstanceOf(Set);

		for (const type of [
			"Program",
			"BlockStatement",
			"StaticBlock",
			"SwitchCase",
		]) {
			expect(astUtils.STATEMENT_LIST_PARENTS.has(type)).toBe(true);
		}

		expect(astUtils.STATEMENT_LIST_PARENTS.has("FunctionDeclaration")).toBe(
			false,
		);
	});

	test("COMMENTS_IGNORE_PATTERN recognizes directive-like comments", () => {
		for (const comment of [
			" eslint-disable-next-line no-console",
			"jshint unused: true",
			"jslint browser",
			"istanbul ignore next",
			"globals foo",
			"exported foo",
			"jscs disallowMultipleLineStrings",
		]) {
			expect(astUtils.COMMENTS_IGNORE_PATTERN.test(comment)).toBe(true);
		}

		expect(astUtils.COMMENTS_IGNORE_PATTERN.test("regular comment")).toBe(
			false,
		);
	});

	test("ECMASCRIPT_GLOBALS contains standard ECMAScript globals only", () => {
		expect(typeof astUtils.ECMASCRIPT_GLOBALS).toBe("object");
		expect(astUtils.ECMASCRIPT_GLOBALS).toHaveProperty("Object");
		expect(astUtils.ECMASCRIPT_GLOBALS).toHaveProperty("Array");
		expect(astUtils.ECMASCRIPT_GLOBALS).toHaveProperty("parseInt");
		expect(astUtils.ECMASCRIPT_GLOBALS).toHaveProperty("undefined");
		expect(astUtils.ECMASCRIPT_GLOBALS).not.toHaveProperty("require");
		expect(astUtils.ECMASCRIPT_GLOBALS.Object).toBe(false);
	});

	test("createGlobalLinebreakMatcher returns a fresh global matcher", () => {
		const first = astUtils.createGlobalLinebreakMatcher();
		const second = astUtils.createGlobalLinebreakMatcher();

		expect(first).not.toBe(second);
		expect(first.global).toBe(true);
		expect("a\r\nb\nc".replace(first, "|")).toBe("a|b|c");
	});
});

//------------------------------------------------------------------------------
// Token predicates
//------------------------------------------------------------------------------

describe("punctuation token predicates", () => {
	test.each([
		["isArrowToken", "=>"],
		["isClosingBraceToken", "}"],
		["isClosingBracketToken", "]"],
		["isClosingParenToken", ")"],
		["isColonToken", ":"],
		["isCommaToken", ","],
		["isDotToken", "."],
		["isQuestionDotToken", "?."],
		["isSemicolonToken", ";"],
		["isOpeningBraceToken", "{"],
		["isOpeningBracketToken", "["],
		["isOpeningParenToken", "("],
		["isEqToken", "="],
	])("%s matches only its punctuator", (functionName, value) => {
		const predicate = astUtils[functionName];
		const differentPunctuator = value === "+" ? "-" : "+";

		expect(predicate({ type: "Punctuator", value })).toBe(true);
		expect(
			predicate({ type: "Punctuator", value: differentPunctuator }),
		).toBe(false);
		expect(predicate({ type: "Identifier", value })).toBe(false);
	});

	test.each([
		["isNotClosingBraceToken", "}", "{"],
		["isNotClosingBracketToken", "]", "["],
		["isNotClosingParenToken", ")", "("],
		["isNotColonToken", ":", ","],
		["isNotCommaToken", ",", ";"],
		["isNotDotToken", ".", ","],
		["isNotQuestionDotToken", "?.", "."],
		["isNotOpeningBraceToken", "{", "}"],
		["isNotOpeningBracketToken", "[", "]"],
		["isNotOpeningParenToken", "(", ")"],
		["isNotSemicolonToken", ";", ","],
	])("%s negates the matching predicate", (functionName, value, other) => {
		const predicate = astUtils[functionName];

		expect(predicate({ type: "Punctuator", value: other })).toBe(true);
		expect(predicate({ type: "Punctuator", value })).toBe(false);
	});

	test("isCommentToken recognizes line, block and shebang comments", () => {
		expect(astUtils.isCommentToken({ type: "Line", value: "// x" })).toBe(
			true,
		);
		expect(
			astUtils.isCommentToken({ type: "Block", value: "/* x */" }),
		).toBe(true);
		expect(
			astUtils.isCommentToken({ type: "Shebang", value: "#!/bin/sh" }),
		).toBe(true);
		expect(
			astUtils.isCommentToken({ type: "Identifier", value: "x" }),
		).toBe(false);
	});

	test("isKeywordToken recognizes keyword tokens only", () => {
		expect(astUtils.isKeywordToken({ type: "Keyword", value: "if" })).toBe(
			true,
		);
		expect(
			astUtils.isKeywordToken({ type: "Identifier", value: "if" }),
		).toBe(false);
	});

	test("isTokenOnSameLine compares token line locations", () => {
		const left = { loc: { start: { line: 1 }, end: { line: 3 } } };
		const sameLineRight = { loc: { start: { line: 3 }, end: { line: 3 } } };
		const nextLineRight = { loc: { start: { line: 4 }, end: { line: 4 } } };

		expect(astUtils.isTokenOnSameLine(left, sameLineRight)).toBe(true);
		expect(astUtils.isTokenOnSameLine(left, nextLineRight)).toBe(false);
	});
});

//------------------------------------------------------------------------------
// Node classification
//------------------------------------------------------------------------------

describe("node classification helpers", () => {
	test("isStringLiteral recognizes string literals and template literals", () => {
		expect(astUtils.isStringLiteral(parseExpression('"text"').node)).toBe(
			true,
		);
		expect(astUtils.isStringLiteral(parseExpression("'text'").node)).toBe(
			true,
		);
		expect(astUtils.isStringLiteral(parseExpression("`text`").node)).toBe(
			true,
		);
		expect(astUtils.isStringLiteral(parseExpression("`a${b}`").node)).toBe(
			true,
		);
		expect(astUtils.isStringLiteral(parseExpression("42").node)).toBe(
			false,
		);
		expect(astUtils.isStringLiteral(parseExpression("true").node)).toBe(
			false,
		);
	});

	test("isBreakableStatement recognizes breakable statement types", () => {
		for (const code of [
			"while (a) {}",
			"do {} while (a);",
			"for (;;) {}",
			"for (a in b) {}",
			"for (a of b) {}",
			"switch (a) {}",
		]) {
			expect(astUtils.isBreakableStatement(parse(code).ast.body[0])).toBe(
				true,
			);
		}

		expect(
			astUtils.isBreakableStatement(parse("if (a) {}").ast.body[0]),
		).toBe(false);
	});

	test("isNullLiteral only accepts actual null literals", () => {
		expect(astUtils.isNullLiteral(parseExpression("null").node)).toBe(true);
		expect(astUtils.isNullLiteral(parseExpression("undefined").node)).toBe(
			false,
		);
		expect(astUtils.isNullLiteral(parseExpression("0").node)).toBe(false);
		expect(astUtils.isNullLiteral(parseExpression("/x/").node)).toBe(false);
		expect(astUtils.isNullLiteral(parseExpression("1n").node)).toBe(false);
	});

	test("isNullOrUndefined recognizes null, undefined and void expressions", () => {
		expect(astUtils.isNullOrUndefined(parseExpression("null").node)).toBe(
			true,
		);
		expect(
			astUtils.isNullOrUndefined(parseExpression("undefined").node),
		).toBe(true);
		expect(astUtils.isNullOrUndefined(parseExpression("void 0").node)).toBe(
			true,
		);
		expect(astUtils.isNullOrUndefined(parseExpression("0").node)).toBe(
			false,
		);
		expect(
			astUtils.isNullOrUndefined(parseExpression("nullish").node),
		).toBe(false);
	});

	test("isFunction recognizes all function node types", () => {
		const { ast } = parse(
			"function declared() {}\nconst expression = function () {};\nconst arrow = () => {};",
		);

		expect(astUtils.isFunction(ast.body[0])).toBe(true);
		expect(astUtils.isFunction(ast.body[1].declarations[0].init)).toBe(
			true,
		);
		expect(astUtils.isFunction(ast.body[2].declarations[0].init)).toBe(
			true,
		);
		expect(astUtils.isFunction(null)).toBe(false);
		expect(astUtils.isFunction({ type: "Identifier", name: "f" })).toBe(
			false,
		);
	});

	test("isLoop recognizes loop statements only", () => {
		for (const type of [
			"DoWhileStatement",
			"ForInStatement",
			"ForOfStatement",
			"ForStatement",
			"WhileStatement",
		]) {
			expect(astUtils.isLoop({ type })).toBe(true);
		}

		expect(astUtils.isLoop({ type: "SwitchStatement" })).toBe(false);
		expect(astUtils.isLoop({ type: "IfStatement" })).toBe(false);
		expect(astUtils.isLoop(null)).toBe(false);
	});

	test("isInLoop walks up to the nearest function boundary", () => {
		const inLoop = parse("for (;;) { while (a) { foo(); } }");
		const call = findNode(inLoop.ast, "CallExpression");

		expect(astUtils.isInLoop(call)).toBe(true);
		expect(astUtils.isInLoop(inLoop.ast.body[0])).toBe(true);

		const insideFunction = parse("for (;;) { function f() { foo(); } }");
		expect(
			astUtils.isInLoop(findNode(insideFunction.ast, "CallExpression")),
		).toBe(false);

		const mixed = parse("for (;;) { foo(); } function f() { foo(); }");
		const calls = findNodes(mixed.ast, "CallExpression");

		expect(calls.map(node => astUtils.isInLoop(node))).toEqual([
			true,
			false,
		]);
	});

	test("isCallee checks whether a node is the callee of a call", () => {
		const { ast } = parse("foo.bar(); new Baz();");
		const [call] = findNodes(ast, "CallExpression");
		const [newExpression] = findNodes(ast, "NewExpression");

		expect(astUtils.isCallee(call)).toBe(false);
		expect(astUtils.isCallee(call.callee)).toBe(true);
		expect(astUtils.isCallee(call.callee.object)).toBe(false);
		expect(astUtils.isCallee(newExpression)).toBe(false);
	});

	test("getUpperFunction returns the nearest enclosing function", () => {
		const { ast } = parse("function outer() { const inner = () => 1; }");
		const outer = ast.body[0];
		const arrow = findNode(ast, "ArrowFunctionExpression");

		expect(astUtils.getUpperFunction(outer.body.body[0])).toBe(outer);
		expect(astUtils.getUpperFunction(arrow.body)).toBe(arrow);
		expect(astUtils.getUpperFunction(ast)).toBeNull();
	});

	test("isES5Constructor treats capitalized names as constructors", () => {
		expect(astUtils.isES5Constructor({ id: { name: "Foo" } })).toBe(true);
		expect(astUtils.isES5Constructor({ id: { name: "foo" } })).toBe(false);
		expect(astUtils.isES5Constructor({ id: null })).toBeFalsy();
	});

	test("isSurroundedBy checks the first and last characters", () => {
		expect(astUtils.isSurroundedBy('"abc"', '"')).toBe(true);
		expect(astUtils.isSurroundedBy("'abc'", "'")).toBe(true);
		expect(astUtils.isSurroundedBy("\"abc'", '"')).toBe(false);
		expect(astUtils.isSurroundedBy("abc", "a")).toBe(false);
	});
});

describe("comment and scope helpers", () => {
	test("isDirectiveComment identifies ESLint directive comments", () => {
		expect(
			astUtils.isDirectiveComment({
				type: "Line",
				value: "eslint-disable-next-line no-console",
			}),
		).toBe(true);
		expect(
			astUtils.isDirectiveComment({
				type: "Block",
				value: " eslint-disable no-console ",
			}),
		).toBe(true);
		expect(
			astUtils.isDirectiveComment({
				type: "Block",
				value: " globals foo ",
			}),
		).toBe(true);
		expect(
			astUtils.isDirectiveComment({
				type: "Block",
				value: " global foo ",
			}),
		).toBe(true);
		expect(
			astUtils.isDirectiveComment({
				type: "Block",
				value: " exported foo ",
			}),
		).toBe(true);
		expect(
			astUtils.isDirectiveComment({
				type: "Line",
				value: "globals foo",
			}),
		).toBe(false);
		expect(
			astUtils.isDirectiveComment({
				type: "Block",
				value: " regular comment ",
			}),
		).toBe(false);
	});

	test("getModifyingReferences keeps only first writes per identifier", () => {
		const first = { name: "first" };
		const second = { name: "second" };
		const modifyingFirst = {
			identifier: first,
			init: false,
			isWrite: () => true,
		};
		const duplicateFirst = {
			identifier: first,
			init: false,
			isWrite: () => true,
		};
		const initializer = {
			identifier: second,
			init: true,
			isWrite: () => true,
		};
		const readOnly = {
			identifier: second,
			init: false,
			isWrite: () => false,
		};
		const noIdentifier = { init: false, isWrite: () => true };

		const references = [
			modifyingFirst,
			duplicateFirst,
			initializer,
			readOnly,
			noIdentifier,
		];

		expect(astUtils.getModifyingReferences(references)).toEqual([
			modifyingFirst,
		]);
		expect(references).toHaveLength(5);
	});

	test("getVariableByName searches the scope chain", () => {
		const a = { name: "a" };
		const b = { name: "b" };
		const outer = { set: new Map([["a", a]]), upper: null };
		const inner = { set: new Map([["b", b]]), upper: outer };

		expect(astUtils.getVariableByName(inner, "b")).toBe(b);
		expect(astUtils.getVariableByName(inner, "a")).toBe(a);
		expect(astUtils.getVariableByName(inner, "missing")).toBeNull();
	});

	test("isReferenceToGlobalVariable recognizes free global references", () => {
		const global = parse("foo;", { globals: ["foo"] });

		expect(
			astUtils.isReferenceToGlobalVariable(
				global.scopeManager.scopes[0],
				global.ast.body[0].expression,
			),
		).toBe(true);

		const local = parse("const foo = 1; foo;", { globals: ["foo"] });

		expect(
			astUtils.isReferenceToGlobalVariable(
				local.scopeManager.scopes[0],
				local.ast.body[1].expression,
			),
		).toBe(false);

		const parameter = parse("function f(foo) { return foo; }", {
			globals: ["foo"],
		});
		const fn = parameter.ast.body[0];
		const fnScope = parameter.scopeManager.acquire(fn);

		expect(
			astUtils.isReferenceToGlobalVariable(
				fnScope,
				fn.body.body[0].argument,
			),
		).toBe(false);
	});

	test("isReferenceToGlobalVariable sees globals from inner scopes", () => {
		const { ast, scopeManager } = parse("function f() { foo(); }", {
			globals: ["foo"],
		});
		const fn = ast.body[0];
		const fnScope = scopeManager.acquire(fn);
		const callee = fn.body.body[0].expression.callee;

		expect(astUtils.isReferenceToGlobalVariable(fnScope, callee)).toBe(
			true,
		);
		expect(
			astUtils.isReferenceToGlobalVariable(fnScope, {
				type: "Identifier",
				name: "foo",
			}),
		).toBe(false);
	});

	test("isConstant determines constant truthiness and constant values", () => {
		const cases = [
			["1", true, true],
			['"text"', true, true],
			["/pattern/u", true, true],
			["() => {}", true, true],
			["(function () {})", true, true],
			["({})", true, true],
			["(class {})", true, true],
			["[]", true, true],
			["[1]", true, true],
			["[foo]", true, false],
			["`text`", true, true],
			["`a${foo}`", true, false],
			["`${foo}`", false, false],
			["void 0", true, true],
			["typeof foo", true, false],
			["!foo", false, false],
			["-1", true, true],
			["1 + 2", true, true],
			["foo + 2", false, false],
			["1 in foo", false, false],
			["new Foo()", true, false],
			["foo && false", true, false],
			["foo || true", true, false],
			["1 && 2", true, true],
			["foo && 1", false, false],
			["(foo, 1)", true, true],
			["(1, foo)", false, false],
			["x = 1", true, true],
			["x = foo", false, false],
			["x += 1", false, false],
			["x ||= true", true, false],
			["undefined", true, true],
			["Boolean(1)", true, true],
			["Boolean(foo)", false, false],
			["Boolean()", true, true],
			["foo", false, false],
		];

		for (const [expression, inBooleanPosition, expected] of cases) {
			const { ast, scopeManager } = parse(`${expression};`, {
				globals: ["undefined", "Boolean"],
			});
			const node = ast.body[0].expression;
			const globalScope = scopeManager.scopes[0];

			expect({
				expression,
				booleanPosition: astUtils.isConstant(globalScope, node, true),
				valuePosition: astUtils.isConstant(globalScope, node, false),
			}).toEqual({
				expression,
				booleanPosition: inBooleanPosition,
				valuePosition: expected,
			});
		}
	});

	test("isConstant rejects shadowed undefined and Boolean", () => {
		const parameterUndefined = parse(
			"function f(undefined) { return undefined; }",
		);
		const fn1 = parameterUndefined.ast.body[0];
		const scope1 = parameterUndefined.scopeManager.acquire(fn1);

		expect(
			astUtils.isConstant(
				scope1,
				findNode(fn1, "ReturnStatement").argument,
				true,
			),
		).toBe(false);

		const parameterBoolean = parse(
			"function f(Boolean) { return Boolean(1); }",
		);
		const fn2 = parameterBoolean.ast.body[0];
		const scope2 = parameterBoolean.scopeManager.acquire(fn2);

		expect(
			astUtils.isConstant(
				scope2,
				findNode(fn2, "ReturnStatement").argument,
				true,
			),
		).toBe(false);

		const localBoolean = parse(
			"function f() { const Boolean = value => value; return Boolean(1); }",
		);
		const fn3 = localBoolean.ast.body[0];
		const scope3 = localBoolean.scopeManager.acquire(fn3);

		expect(
			astUtils.isConstant(
				scope3,
				findNode(fn3, "ReturnStatement").argument,
				true,
			),
		).toBe(false);

		const localUndefined = parse("const undefined = 1; undefined;");
		const globalScope = localUndefined.scopeManager.scopes[0];

		expect(
			astUtils.isConstant(
				globalScope,
				localUndefined.ast.body[1].expression,
				true,
			),
		).toBe(false);
	});

	test("isPropertyDescriptor handles Object and Reflect defineProperty calls", () => {
		for (const code of [
			'Object.defineProperty(obj, "x", { value: 1 });',
			'Reflect.defineProperty(obj, "x", { value: 1 });',
		]) {
			const { ast, sourceCode } = parse(code, {
				globals: ["Object", "Reflect"],
			});
			const call = ast.body[0].expression;
			const descriptor = call.arguments[2];

			expect(astUtils.isPropertyDescriptor(descriptor, sourceCode)).toBe(
				true,
			);
		}
	});

	test("isPropertyDescriptor handles descriptor maps for create and defineProperties", () => {
		for (const code of [
			"Object.create(null, { x: { value: 1 } });",
			"Object.defineProperties(obj, { x: { value: 1 } });",
		]) {
			const { ast, sourceCode } = parse(code, { globals: ["Object"] });
			const call = ast.body[0].expression;
			const descriptor = call.arguments[1].properties[0].value;

			expect(astUtils.isPropertyDescriptor(descriptor, sourceCode)).toBe(
				true,
			);
		}
	});

	test("isPropertyDescriptor rejects objects outside descriptor positions", () => {
		const ordinary = parse("const descriptor = { value: 1 };", {
			globals: ["Object"],
		});

		expect(
			astUtils.isPropertyDescriptor(
				ordinary.ast.body[0].declarations[0].init,
				ordinary.sourceCode,
			),
		).toBe(false);

		const argument = parse("foo({ value: 1 });", {
			globals: ["Object"],
		});

		expect(
			astUtils.isPropertyDescriptor(
				argument.ast.body[0].expression.arguments[0],
				argument.sourceCode,
			),
		).toBe(false);

		const someObject = parse(
			'SomeObject.defineProperty(obj, "x", { value: 1 });',
			{ globals: ["Object"] },
		);

		expect(
			astUtils.isPropertyDescriptor(
				someObject.ast.body[0].expression.arguments[2],
				someObject.sourceCode,
			),
		).toBe(false);
	});

	test("isPropertyDescriptor rejects shadowed Object globals", () => {
		const { ast, sourceCode } = parse(
			'function f(Object) { Object.defineProperty(obj, "x", { value: 1 }); }',
			{ globals: ["Object"] },
		);
		const call = findNode(ast, "CallExpression");

		expect(
			astUtils.isPropertyDescriptor(call.arguments[2], sourceCode),
		).toBe(false);
	});
});

describe("isDefaultThisBinding", () => {
	test.each([
		["function foo() {}", true, true],
		["function Foo() {}", false, true],
		["({ foo() {} })", false, false],
		["({ foo: function () {} })", false, false],
		["({ foo: function bar() {} })", false, false],
		["class A { foo = function () {}; }", false, false],
		["foo = function () {}", true, true],
		["Foo = function () {}", false, true],
		["var foo = function () {}", true, true],
		["var Foo = function () {}", false, true],
		["var Foo = function bar() {}", true, true],
		["(function foo() {}).bind(obj)", false, false],
		["(function foo() {}).bind(null)", true, true],
		["[].forEach(function () {}, obj)", false, false],
		["[].forEach(function () {})", true, true],
		["Reflect.apply(function () {}, obj, [])", false, false],
		["Array.from([], function () {}, obj)", false, false],
		["foo(function bar() {})", true, true],
		["cond ? function () {} : null", true, true],
		["Object.assign({}, { m() {} })", false, false],
	])(
		"evaluates this binding for %s",
		(code, expected, expectedWithoutConstructorCap) => {
			const { ast, sourceCode } = parse(code);
			const fn = findFunction(ast);

			expect(fn).toBeDefined();
			expect(astUtils.isDefaultThisBinding(fn, sourceCode)).toBe(
				expected,
			);
			expect(
				astUtils.isDefaultThisBinding(fn, sourceCode, {
					capIsConstructor: false,
				}),
			).toBe(expectedWithoutConstructorCap);
		},
	);

	test("class static blocks never have default this binding", () => {
		const { ast, sourceCode } = parse("class A { static {} }");
		const staticBlock = findNode(ast, "StaticBlock");

		expect(astUtils.isDefaultThisBinding(staticBlock, sourceCode)).toBe(
			false,
		);
	});

	test("JSDoc @this tags disable default this binding", () => {
		const declaration = parse("/* @this */ function foo() {}");

		expect(
			astUtils.isDefaultThisBinding(
				findFunction(declaration.ast),
				declaration.sourceCode,
			),
		).toBe(false);

		const callback = parse(
			"sinon.test(/* @this sandbox */ function () {});",
		);

		expect(
			astUtils.isDefaultThisBinding(
				findFunction(callback.ast),
				callback.sourceCode,
			),
		).toBe(false);
	});

	test("non-JSDoc block comments do not affect this binding", () => {
		const { ast, sourceCode } = parse(
			"/* regular comment */ function foo() {}",
		);

		expect(
			astUtils.isDefaultThisBinding(findFunction(ast), sourceCode),
		).toBe(true);
	});
});

