describe("getNameLocationInGlobalDirectiveComment", () => {
	test("locates names in a single-line globals comment", () => {
		const { ast, sourceCode } = parse("/* globals foo, bar */\nfoo();");
		const comment = ast.comments[0];

		expect(
			astUtils.getNameLocationInGlobalDirectiveComment(
				sourceCode,
				comment,
				"foo",
			),
		).toEqual({
			start: { line: 1, column: 11 },
			end: { line: 1, column: 14 },
		});
		expect(
			astUtils.getNameLocationInGlobalDirectiveComment(
				sourceCode,
				comment,
				"bar",
			),
		).toEqual({
			start: { line: 1, column: 16 },
			end: { line: 1, column: 19 },
		});
	});

	test("falls back to the start of the comment value for unknown names", () => {
		const { ast, sourceCode } = parse("/* globals foo, bar */\nfoo();");
		const comment = ast.comments[0];

		expect(
			astUtils.getNameLocationInGlobalDirectiveComment(
				sourceCode,
				comment,
				"baz",
			),
		).toEqual({
			start: { line: 1, column: 2 },
			end: { line: 1, column: 3 },
		});
	});

	test("locates names across multiple comment lines", () => {
		const { ast, sourceCode } = parse("/* globals\n   foo */\nfoo();");
		const comment = ast.comments[0];

		expect(
			astUtils.getNameLocationInGlobalDirectiveComment(
				sourceCode,
				comment,
				"foo",
			),
		).toEqual({
			start: { line: 2, column: 3 },
			end: { line: 2, column: 6 },
		});
	});

	test("locates names terminated by a colon", () => {
		const { ast, sourceCode } = parse("/* globals foo:readonly */\nfoo();");
		const comment = ast.comments[0];

		expect(
			astUtils.getNameLocationInGlobalDirectiveComment(
				sourceCode,
				comment,
				"foo",
			),
		).toEqual({
			start: { line: 1, column: 11 },
			end: { line: 1, column: 14 },
		});
	});
});

