				),
			).toBe(expected);
		},
	);

	test("isArrayFromMethod recognizes Array and typed array from methods", () => {
		for (const code of [
			"Array.from(x)",
			"Int32Array.from(x)",
			"Array.from?.(x)",
		]) {
			const { node } = parseExpression(code);
			const callee =
				node.type === "ChainExpression"
					? node.expression.callee
					: node.callee;

			expect(astUtils.isArrayFromMethod(callee)).toBe(true);
		}

		for (const code of ["Array.of(x)", "Foo.from(x)", "[].map(x)"]) {
			expect(
				astUtils.isArrayFromMethod(parseExpression(code).node.callee),
			).toBe(false);
		}
	});

	test("isArrayFromAsyncMethod recognizes only Array.fromAsync", () => {
		expect(
			astUtils.isArrayFromAsyncMethod(
				parseExpression("Array.fromAsync(x)").node.callee,
			),
		).toBe(true);
		expect(
			astUtils.isArrayFromAsyncMethod(
				parseExpression("Array.from(x)").node.callee,
			),
		).toBe(false);
	});

	test("equalLiteralValue compares literal values", () => {
		const pairs = [
			['"a"', "'a'", true],
			["1", "1", true],
			["1", "2", false],
			["1n", "1n", true],
			["1n", "2n", false],
			["null", "null", true],
			["null", "undefined", false],
			["/a/g", "/a/g", true],
			["/a/g", "/a/i", false],
			["/a/g", "/b/g", false],
		];

		for (const [leftCode, rightCode, expected] of pairs) {
			const { left, right } = parseTwoExpressions(leftCode, rightCode);

			expect(astUtils.equalLiteralValue(left, right)).toBe(expected);
		}
	});

	test.each([
		["a", "a", true, true],
		["a", "b", false, false],
		["a.b", 'a["b"]', true, false],
		["a.b", 'a["c"]', false, false],
		["a[b]", "a[b]", true, true],
		["a[b]", "a[c]", false, false],
		["a?.b", "a.b", true, true],
		["this", "this", true, true],
		["1", "1", true, true],
		["1", "2", false, false],
		["/a/g", "/a/g", true, true],
		["'a'", '"a"', true, true],
	])(
		"isSameReference compares %s and %s",
		(leftCode, rightCode, expected, expectedWithoutStaticKeys) => {
			const { left, right } = parseTwoExpressions(leftCode, rightCode);

			expect(astUtils.isSameReference(left, right)).toBe(expected);
			expect(astUtils.isSameReference(left, right, true)).toBe(
				expectedWithoutStaticKeys,
			);
		},
	);
});

describe("logical expression helpers", () => {
	test("isLogicalExpression recognizes && and || only", () => {
		expect(
			astUtils.isLogicalExpression(parseExpression("a && b").node),
		).toBe(true);
		expect(
			astUtils.isLogicalExpression(parseExpression("a || b").node),
		).toBe(true);
		expect(
			astUtils.isLogicalExpression(parseExpression("a ?? b").node),
		).toBe(false);
		expect(
			astUtils.isLogicalExpression(parseExpression("a + b").node),
		).toBe(false);
	});

	test("isCoalesceExpression recognizes ?? only", () => {
		expect(
			astUtils.isCoalesceExpression(parseExpression("a ?? b").node),
		).toBe(true);
		expect(
			astUtils.isCoalesceExpression(parseExpression("a || b").node),
		).toBe(false);
	});

	test("isMixedLogicalAndCoalesceExpressions detects mixed pairs", () => {
		const logical = parseExpression("a && b").node;
		const coalesce = parseExpression("a ?? b").node;
		const otherLogical = parseExpression("a || b").node;

		expect(
			astUtils.isMixedLogicalAndCoalesceExpressions(logical, coalesce),
		).toBe(true);
		expect(
			astUtils.isMixedLogicalAndCoalesceExpressions(
				coalesce,
				otherLogical,
			),
		).toBe(true);
		expect(
			astUtils.isMixedLogicalAndCoalesceExpressions(
				logical,
				otherLogical,
			),
		).toBe(false);
		expect(
			astUtils.isMixedLogicalAndCoalesceExpressions(coalesce, coalesce),
		).toBe(false);
	});

	test("isLogicalAssignmentOperator recognizes logical assignments", () => {
		expect(astUtils.isLogicalAssignmentOperator("&&=")).toBe(true);
		expect(astUtils.isLogicalAssignmentOperator("||=")).toBe(true);
		expect(astUtils.isLogicalAssignmentOperator("??=")).toBe(true);
		expect(astUtils.isLogicalAssignmentOperator("=")).toBe(false);
		expect(astUtils.isLogicalAssignmentOperator("+=")).toBe(false);
		expect(astUtils.isLogicalAssignmentOperator("&&")).toBe(false);
	});

	test("getSwitchCaseColonToken returns the colon of each case", () => {
		const code = "switch (a) { case 1: foo(); break; default: bar(); }";
		const { ast, sourceCode } = parse(code);
		const cases = findNodes(ast, "SwitchCase");
		const colons = cases.map(node =>
			astUtils.getSwitchCaseColonToken(node, sourceCode),
		);

		expect(colons.map(token => token.value)).toEqual([":", ":"]);
		expect(colons.map(token => token.type)).toEqual([
			"Punctuator",
			"Punctuator",
		]);
		expect(colons[0].range[0]).toBe(
			code.indexOf(":", cases[0].test.range[1]),
		);
		expect(colons[1].range[0]).toBe(code.indexOf(":", cases[1].range[0]));
	});

	test("getModuleExportName handles identifiers and string literals", () => {
		expect(
			astUtils.getModuleExportName({ type: "Identifier", name: "foo" }),
		).toBe("foo");
		expect(
			astUtils.getModuleExportName({ type: "Literal", value: "foo-bar" }),
		).toBe("foo-bar");
	});
});

