		["({})", false],
		["[]", false],
		["x = foo()", true],
		["x = 1", false],
		["x += foo()", false],
		["x -= foo()", false],
		["x &&= foo()", true],
		["x &&= 1", false],
		["x ||= 1", true],
		["x ??= foo()", true],
		["(foo(), 1)", false],
		["(1, foo())", true],
		["foo && bar", true],
		["foo && 1", false],
		["1 || foo", true],
