describe("canTokensBeAdjacent", () => {
	test.each([
		["+", "+", false],
		["+", "++", false],
		["-", "--", false],
		["-", "+", true],
		["/", "/* block */", false],
		["/", "// line\n", false],
		["a", "b", false],
		["a", "/* block */", true],
		["a", "// line\n", true],
		['"a"', '"b"', true],
		["`a`", "b", true],
		["a", "#b", true],
		["1", ".5", false],
		["a", ".5", true],
		["#!/usr/bin/env node", "foo", false],
		["a", "1", false],
		['"', "a", false],
		["a", '"', false],
	])("canTokensBeAdjacent(%j, %j) is %s", (left, right, expected) => {
		expect(astUtils.canTokensBeAdjacent(left, right)).toBe(expected);
	});

	test("accepts token objects and rejects shebang tokens", () => {
		expect(
			astUtils.canTokensBeAdjacent(
				{ type: "Punctuator", value: "+" },
				{ type: "Punctuator", value: "+" },
			),
		).toBe(false);
		expect(
			astUtils.canTokensBeAdjacent(
				{ type: "Punctuator", value: "+" },
				{ type: "Identifier", value: "a" },
			),
		).toBe(true);
		expect(
			astUtils.canTokensBeAdjacent(
				{ type: "Shebang", value: "#!/bin/sh" },
				{ type: "Identifier", value: "a" },
			),
		).toBe(false);
		expect(
			astUtils.canTokensBeAdjacent(
				{ type: "Identifier", value: "a" },
				{ type: "Punctuator", value: "/" },
			),
		).toBe(true);
	});
});

